The grammar is a standard recursive-descent parser with one level per precedence tier:

- expr: term (('+'|'-') term)*
- term: unary (('*'|'/') unary)*
- unary: ('+'|'-') unary | power
- power: atom ('**' unary)?
- atom: number | '(' expr ')'

Putting unary below `**` gives `-2**2 == -(2**2) == -4`, and letting the exponent be a `unary` gives `2**-1 == 1/2` and right-associativity through `power` recursing on itself. Numbers are read as runs of digits and converted to `Fraction`, so every intermediate value stays exact. An exponent that is not an integer raises ValueError, and so does any syntax error or leftover input. Division by zero raises ZeroDivisionError, which the spec permits.

```python
import fractions
import re

_TOKEN = re.compile(r"\s*(\*\*|[-+*/()]|\d+)")


def _tokenize(s: str) -> list[str]:
    tokens = []
    pos = 0
    s = s.rstrip()
    while pos < len(s):
        m = _TOKEN.match(s, pos)
        if not m:
            raise ValueError(f"unexpected character at position {pos}")
        tokens.append(m.group(1))
        pos = m.end()
    return tokens


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.i = 0

    def peek(self):
        return self.tokens[self.i] if self.i < len(self.tokens) else None

    def take(self):
        tok = self.peek()
        if tok is None:
            raise ValueError("unexpected end of input")
        self.i += 1
        return tok

    def parse(self):
        value = self.expr()
        if self.peek() is not None:
            raise ValueError(f"unexpected token {self.peek()!r}")
        return value

    def expr(self):
        value = self.term()
        while self.peek() in ("+", "-"):
            op = self.take()
            rhs = self.term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def term(self):
        value = self.unary()
        while self.peek() in ("*", "/"):
            op = self.take()
            rhs = self.unary()
            if op == "*":
                value = value * rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                value = value / rhs
        return value

    def unary(self):
        if self.peek() in ("+", "-"):
            op = self.take()
            v = self.unary()
            return v if op == "+" else -v
        return self.power()

    def power(self):
        base = self.atom()
        if self.peek() == "**":
            self.take()
            exp = self.unary()
            if exp.denominator != 1:
                raise ValueError("exponent must be an integer")
            e = int(exp)
            if base == 0 and e < 0:
                raise ZeroDivisionError("zero to a negative power")
            return base ** e
        return base

    def atom(self):
        tok = self.take()
        if tok == "(":
            value = self.expr()
            if self.take() != ")":
                raise ValueError("expected ')'")
            return value
        if tok.isdigit():
            return fractions.Fraction(int(tok))
        raise ValueError(f"unexpected token {tok!r}")


def evaluate(s: str) -> fractions.Fraction:
    if not isinstance(s, str):
        raise ValueError("input must be a string")
    tokens = _tokenize(s)
    if not tokens:
        raise ValueError("empty expression")
    return _Parser(tokens).parse()
```

Splitting both strings on "/" gives segments in which the separator is no longer ambiguous. A segment-level recursive matcher then handles "**" by trying zero segments or consuming one path segment, and a character-level matcher inside each segment handles "?" and "*". Both `*` and `?` are confined to a single segment because the path has already been split, so they cannot cross a "/". Splitting "" gives `[""]`, which must be treated as zero segments, so I special-case it to make `glob_match("**", "")` true while `glob_match("a", "")` stays false.

Recursion depth is bounded by the number of segments, and the `**` branching is memoized, so the matcher stays polynomial even on long patterns.

```python
from functools import lru_cache


def _segment_match(pat: str, seg: str) -> bool:
    # Iterative dynamic programming over the two strings; '*' stays within a segment.
    n, m = len(pat), len(seg)
    dp = [[False] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = True
    for i in range(1, n + 1):
        if pat[i - 1] == "*":
            dp[i][0] = dp[i - 1][0]
    for i in range(1, n + 1):
        pc = pat[i - 1]
        for j in range(1, m + 1):
            if pc == "*":
                dp[i][j] = dp[i - 1][j] or dp[i][j - 1]
            elif pc == "?" or pc == seg[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
    return dp[n][m]


def glob_match(pattern: str, path: str) -> bool:
    pat_segs = tuple(pattern.split("/"))
    path_segs = () if path == "" else tuple(path.split("/"))

    @lru_cache(maxsize=None)
    def go(pi: int, si: int) -> bool:
        if pi == len(pat_segs):
            return si == len(path_segs)
        p = pat_segs[pi]
        if p == "**":
            if go(pi + 1, si):
                return True
            return si < len(path_segs) and go(pi, si + 1)
        if si == len(path_segs):
            return False
        if not _segment_match(p, path_segs[si]):
            return False
        return go(pi + 1, si + 1)

    return go(0, 0)
```

