Kahn's algorithm with a min-heap gives the required order: every node enters the heap only once all its dependencies are placed, and the heap always yields the alphabetically smallest ready node. Nodes that appear only as dependencies are collected from the values, and a cycle is detected when fewer nodes are emitted than exist.

```python
import heapq


def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    nodes = set(deps)
    for targets in deps.values():
        nodes.update(targets)

    indegree = {n: 0 for n in nodes}
    dependents = {n: [] for n in nodes}
    for node, prereqs in deps.items():
        for p in set(prereqs):
            indegree[node] += 1
            dependents[p].append(node)

    heap = [n for n in nodes if indegree[n] == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        n = heapq.heappop(heap)
        order.append(n)
        for d in dependents[n]:
            indegree[d] -= 1
            if indegree[d] == 0:
                heapq.heappush(heap, d)

    if len(order) != len(nodes):
        raise ValueError("dependency cycle detected")
    return order
```

Counting weekdays in a range can be done in closed form instead of day by day, which keeps it fast for ranges of millions of days. Weekdays in [start, end) can be found by taking whole weeks and handling the remainder. A simple approach is to count weekdays from a fixed reference date using the ordinal: let `f(d)` be the number of weekdays strictly before day ordinal `d` relative to a reference Monday. Then the weekday count is `f(end) - f(start)`. Holidays that are weekdays inside the range are then subtracted by iterating over the holidays set, which is small, so that step costs O(|holidays|).

For `f`, use the ordinal with `date.toordinal()`, where ordinal 1 is 0001-01-01 and is a Monday. Weeks are 7 days, so the number of weekdays in the first `k` days starting from ordinal 1 is `5 * (k // 7) + min(k % 7, 5)`. Let `k = o - 1` for an ordinal `o`, so that `f(o)` counts weekdays among ordinals 1 through `o - 1`. The count for [start, end) is then `f(end_ord) - f(start_ord)`.

For the holidays, a holiday counts only if it is a weekday and lies in the range. That is checked directly for each holiday.

Sign handling: if `end < start`, compute the count for [end, start) and negate it, which matches the spec.

```python
import datetime


def _weekdays_before(ordinal: int) -> int:
    # Weekdays among ordinals 1 .. ordinal-1; ordinal 1 (0001-01-01) is a Monday.
    k = ordinal - 1
    return 5 * (k // 7) + min(k % 7, 5)


def _count(start: datetime.date, end: datetime.date, holidays: set[datetime.date]) -> int:
    s = start.toordinal()
    e = end.toordinal()
    total = _weekdays_before(e) - _weekdays_before(s)
    for h in holidays:
        if s <= h.toordinal() < e and h.weekday() < 5:
            total -= 1
    return total


def business_days(start: datetime.date, end: datetime.date, holidays: set[datetime.date]) -> int:
    if end < start:
        return -_count(end, start, holidays)
    return _count(start, end, holidays)
```

```python
import fractions
import re


_TOKEN_RE = re.compile(r"\s*(?:(\d+)|(\*\*|[-+*/()]))")


def _tokenize(s):
    tokens = []
    pos = 0
    n = len(s)
    while True:
        while pos < n and s[pos].isspace():
            pos += 1
        if pos >= n:
            break
        m = _TOKEN_RE.match(s, pos)
        if not m or m.end() == pos:
            raise ValueError("invalid character at position %d" % pos)
        if m.group(1) is not None:
            tokens.append(("num", int(m.group(1))))
        else:
            tokens.append(("op", m.group(2)))
        pos = m.end()
    return tokens


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.i = 0

    def peek(self):
        return self.tokens[self.i] if self.i < len(self.tokens) else None

    def advance(self):
        tok = self.peek()
        if tok is None:
            raise ValueError("unexpected end of input")
        self.i += 1
        return tok

    def is_op(self, tok, *ops):
        return tok is not None and tok[0] == "op" and tok[1] in ops

    # expr := term (('+'|'-') term)*
    def parse_expr(self):
        value = self.parse_term()
        while self.is_op(self.peek(), "+", "-"):
            op = self.advance()[1]
            rhs = self.parse_term()
            value = value + rhs if op == "+" else value - rhs
        return value

    # term := unary (('*'|'/') unary)*
    def parse_term(self):
        value = self.parse_unary()
        while self.is_op(self.peek(), "*", "/"):
            op = self.advance()[1]
            rhs = self.parse_unary()
            if op == "*":
                value = value * rhs
            else:
                if rhs == 0:
                    raise ValueError("division by zero")
                value = value / rhs
        return value

    # unary := ('+'|'-') unary | power
    def parse_unary(self):
        if self.is_op(self.peek(), "+", "-"):
            op = self.advance()[1]
            operand = self.parse_unary()
            return -operand if op == "-" else +operand
        return self.parse_power()

    # power := atom ['**' unary]   (right-associative; exponent may be signed)
    def parse_power(self):
        base = self.parse_atom()
        if self.is_op(self.peek(), "**"):
            self.advance()
            exp = self.parse_unary()
            if exp.denominator != 1:
                raise ValueError("exponent must be an integer")
            e = int(exp)
            if e < 0 and base == 0:
                raise ValueError("zero cannot be raised to a negative power")
            return base ** e
        return base

    # atom := NUMBER | '(' expr ')'
    def parse_atom(self):
        tok = self.advance()
        if tok[0] == "num":
            return fractions.Fraction(tok[1])
        if tok[1] == "(":
            value = self.parse_expr()
            closing = self.advance()
            if not self.is_op(closing, ")"):
                raise ValueError("expected ')'")
            return value
        raise ValueError("unexpected token %r" % (tok[1],))


def evaluate(s: str) -> fractions.Fraction:
    if not isinstance(s, str):
        raise ValueError("input must be a string")
    tokens = _tokenize(s)
    if not tokens:
        raise ValueError("empty expression")
    parser = _Parser(tokens)
    result = parser.parse_expr()
    if parser.peek() is not None:
        raise ValueError("unexpected trailing input")
    return fractions.Fraction(result)
```

