I'll keep this to the standard library: a Kahn's algorithm with a min-heap gives the alphabetically smallest ready node at each step, and a leftover count of unprocessed nodes detects cycles. numpy isn't needed for this, since the work is graph bookkeeping rather than array arithmetic, and avoiding it keeps the module dependency-free like the earlier ones.

```python
import heapq


def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    # Collect every node, including those mentioned only as dependencies.
    nodes = set(deps.keys())
    for targets in deps.values():
        nodes.update(targets)

    # dependents[d] = nodes that depend on d; indegree[n] = number of
    # distinct dependencies of n still unprocessed.
    dependents = {n: [] for n in nodes}
    indegree = {n: 0 for n in nodes}
    for node, targets in deps.items():
        for d in set(targets):  # ignore duplicate listings
            dependents[d].append(node)
            indegree[node] += 1

    heap = [n for n in nodes if indegree[n] == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        n = heapq.heappop(heap)
        order.append(n)
        for m in dependents[n]:
            indegree[m] -= 1
            if indegree[m] == 0:
                heapq.heappush(heap, m)

    if len(order) != len(nodes):
        raise ValueError("dependency cycle detected")
    return order
```

The count of weekdays in a range can be done in constant time: take the number of whole weeks, which contribute five weekdays each, and then count the leftover days by weekday. Holidays are then subtracted individually, but only the ones inside the range, so the cost depends on the number of holidays rather than the length of the range. Since the spec asks for speed on ranges of millions of days, I'm avoiding a day-by-day loop entirely.

```python
import datetime


def _weekdays_before(d: datetime.date) -> int:
    # Number of weekdays in the half-open range [epoch, d) for a fixed
    # reference epoch, using ordinal arithmetic so it is O(1).
    # Reference: ordinal 1 (0001-01-01) is a Monday.
    n = d.toordinal() - 1  # days elapsed since 0001-01-01 (a Monday)
    weeks, rem = divmod(n, 7)
    return weeks * 5 + min(rem, 5)


def _count_range(start: datetime.date, end: datetime.date,
                 holidays: set[datetime.date]) -> int:
    # Count weekdays in [start, end) not in holidays, assuming start <= end.
    total = _weekdays_before(end) - _weekdays_before(start)
    for h in holidays:
        if start <= h < end and h.weekday() < 5:
            total -= 1
    return total


def business_days(start: datetime.date, end: datetime.date,
                  holidays: set[datetime.date]) -> int:
    if end < start:
        return -_count_range(end, start, holidays)
    return _count_range(start, end, holidays)
```

Hello there! 👋 Here's the canonical JSON encoder. 🎉

The main points: sort dict keys by their UTF-16 code units (not Python's code point order, which differs for characters above U+FFFF), escape only the required control characters with lowercase hex, and write everything else literally with no whitespace. Booleans must be checked before ints, since `bool` is a subclass of `int` in Python.

```python
def _utf16_key(s: str):
    # Sort key: the sequence of UTF-16 code units of s.
    return list(s.encode("utf-16-be", "surrogatepass").decode("utf-16-be").encode("utf-16-be"))


def _utf16_units(s: str) -> list[int]:
    b = s.encode("utf-16-be", "surrogatepass")
    return [int.from_bytes(b[i:i + 2], "big") for i in range(0, len(b), 2)]


_ESCAPES = {
    '"': '\\"',
    "\\": "\\\\",
    "\b": "\\b",
    "\f": "\\f",
    "\n": "\\n",
    "\r": "\\r",
    "\t": "\\t",
}


def _encode_string(s: str) -> str:
    out = ['"']
    for ch in s:
        if ch in _ESCAPES:
            out.append(_ESCAPES[ch])
        elif ord(ch) < 0x20:
            out.append("\\u%04x" % ord(ch))
        else:
            out.append(ch)
    out.append('"')
    return "".join(out)


def canonical_json(v) -> str:
    if v is None:
        return "null"
    if v is True:
        return "true"
    if v is False:
        return "false"
    if isinstance(v, int):
        return str(int(v))
    if isinstance(v, str):
        return _encode_string(v)
    if isinstance(v, list):
        return "[" + ",".join(canonical_json(x) for x in v) + "]"
    if isinstance(v, dict):
        keys = sorted(v.keys(), key=_utf16_units)
        members = [_encode_string(k) + ":" + canonical_json(v[k]) for k in keys]
        return "{" + ",".join(members) + "}"
    raise TypeError("unsupported type: %r" % type(v).__name__)
```

