        "B": [("C", 2), ("D", 5)],
        "C": [("D", 1)],
        "D": [],
    }
    print(shortest_path(g, "A", "D"))
    print(shortest_path(g, "A", "A"))
    print(shortest_path(g, "D", "A"))
