import fractions
import re

_TOKEN_RE = re.compile(r"\s*(?:(\d+)|(\*\*|[-+*/()]))")


def _tokenize(s):
    tokens = []
    pos = 0
    n = len(s)
    while pos < n:
        if s[pos].isspace():
            pos += 1
            continue
        m = _TOKEN_RE.match(s, pos)
        if not m or m.end() == pos:
            raise ValueError("invalid character at position %d" % pos)
        if m.group(1) is not None:
            tokens.append(("num", int(m.group(1))))
        else:
            tokens.append(("op", m.group(2)))
        pos = m.end()
    return tokens


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.i = 0

    def peek(self):
        return self.tokens[self.i] if self.i < len(self.tokens) else None

    def advance(self):
        tok = self.peek()
        if tok is None:
            raise ValueError("unexpected end of input")
        self.i += 1
        return tok

    def is_op(self, tok, value):
        return tok is not None and tok[0] == "op" and tok[1] == value

    def parse(self):
        value = self.expr()
        if self.peek() is not None:
            raise ValueError("unexpected token")
        return value

    # expr := term (('+'|'-') term)*
    def expr(self):
        value = self.term()
        while True:
            tok = self.peek()
            if self.is_op(tok, "+"):
                self.advance()
                value = value + self.term()
            elif self.is_op(tok, "-"):
                self.advance()
                value = value - self.term()
            else:
                return value

    # term := unary (('*'|'/') unary)*
    def term(self):
        value = self.unary()
        while True:
            tok = self.peek()
            if self.is_op(tok, "*"):
                self.advance()
                value = value * self.unary()
            elif self.is_op(tok, "/"):
                self.advance()
                divisor = self.unary()
                if divisor == 0:
                    raise ValueError("division by zero")
                value = value / divisor
            else:
                return value

    # unary := ('+'|'-') unary | power
    def unary(self):
        tok = self.peek()
        if self.is_op(tok, "+"):
            self.advance()
            return self.unary()
        if self.is_op(tok, "-"):
            self.advance()
            return -self.unary()
        return self.power()

    # power := atom ('**' unary)?   (right-associative, exponent may be signed)
    def power(self):
        base = self.atom()
        if self.is_op(self.peek(), "**"):
            self.advance()
            exp = self.unary()
            if exp.denominator != 1:
                raise ValueError("exponent must be an integer")
            e = int(exp)
            if base == 0 and e < 0:
                raise ValueError("division by zero")
            return base ** e
        return base

    # atom := NUMBER | '(' expr ')'
    def atom(self):
        tok = self.advance()
        if tok[0] == "num":
            return fractions.Fraction(tok[1])
        if tok[1] == "(":
            value = self.expr()
            closing = self.advance()
            if not self.is_op(closing, ")"):
                raise ValueError("expected ')'")
            return value
        raise ValueError("unexpected token")


def evaluate(s: str) -> fractions.Fraction:
    if not isinstance(s, str):
        raise ValueError("input must be a string")
    tokens = _tokenize(s)
    if not tokens:
        raise ValueError("empty expression")
    result = _Parser(tokens).parse()
    return fractions.Fraction(result)
```

I'll write a recursive-descent parser over a tokenizer, using `fractions.Fraction` for every value so results stay exact. The grammar is: expr → term (('+'|'-') term)*; term → unary (('*'|'/') unary)*; unary → ('+'|'-') unary | power; power → atom ('**' unary)?, where the exponent is parsed as a unary so that `2**-1` works and `**` is right-associative, while unary minus sits below `**` so `-2**2` is `-(2**2)`. Atoms are integers or parenthesised expressions. For `**`, the exponent must be an integer-valued Fraction; a negative integer exponent on a zero base is a division by zero and I'll raise ValueError for that. Recursion depth follows nesting, which is fine for normal inputs, and the parser checks that all input is consumed.

