def glob_match(pattern: str, path: str) -> bool:
    pat_segs = pattern.split("/")
    path_segs = path.split("/")

    def seg_match(p: str, s: str) -> bool:
        # Iterative wildcard match within a single segment: '?' one char, '*' any run.
        pi = si = 0
        star_pi = -1
        star_si = 0
        while si < len(s):
            if pi < len(p) and (p[pi] == "?" or p[pi] == s[si]):
                pi += 1
                si += 1
            elif pi < len(p) and p[pi] == "*":
                star_pi = pi
                star_si = si
                pi += 1
            elif star_pi != -1:
                pi = star_pi + 1
                star_si += 1
                si = star_si
            else:
                return False
        while pi < len(p) and p[pi] == "*":
            pi += 1
        return pi == len(p)

    # Iterative matching of segment lists with "**" matching zero or more segments.
    # Memoised DP over (pattern index, path index) to avoid exponential blowup.
    n, m = len(pat_segs), len(path_segs)
    memo = {}

    def solve(i: int, j: int) -> bool:
        key = (i, j)
        if key in memo:
            return memo[key]
        if i == n:
            result = j == m
        elif pat_segs[i] == "**":
            # Zero segments, or consume one path segment and stay on "**".
            result = solve(i + 1, j) or (j < m and solve(i, j + 1))
        else:
            result = (
                j < m
                and seg_match(pat_segs[i], path_segs[j])
                and solve(i + 1, j + 1)
            )
        memo[key] = result
        return result

    # Recursion depth is bounded by segment counts; use an explicit iterative
    # fill to be safe on long inputs.
    # Bottom-up table over (i from n down to 0, j from m down to 0).
    table = [[False] * (m + 1) for _ in range(n + 1)]
    table[n][m] = True
    for i in range(n, -1, -1):
        for j in range(m, -1, -1):
            if i == n:
                if j == m:
                    table[i][j] = True
                continue
            if pat_segs[i] == "**":
                val = table[i + 1][j]
                if not val and j < m:
                    val = table[i][j + 1]
                table[i][j] = val
            else:
                table[i][j] = (
                    j < m
                    and seg_match(pat_segs[i], path_segs[j])
                    and table[i + 1][j + 1]
                )
    return table[0][0]
